/** A Swell event as a model function receives it */
export function swellEvent(type: string, data: Record<string, unknown> = {}, delivery: Record<string, unknown> = {}) {
  return { id: "6ac93eb7ad5799fa4bd63e92", type, model: type.split(".")[0] + "s", data, delivery: { attempts: 0, ...delivery } };
}
